   181	  const bf16* k_src = kg + batch_kv + static_cast<int64_t>(kv_head) * kDim +
   182	                      row_local * kv_pitch + col;
   183	  const bf16* v_src = vg + batch_kv + static_cast<int64_t>(kv_head) * kDim +
   184	                      row_local * kv_pitch + col;
   185	  bf16* q_dst = q_smem + row_local * kRowStride + col;
   186	  bf16* k_dst = k_smem + row_local * kRowStride + col;
   187	  bf16* v_dst = v_smem + row_local * kRowStride + col;
   188	
   189	  // --- Q tile stays resident for the whole KV loop -------------------------
   190	  stage_tile(q_dst, q_src, q_pitch, step_rows);
   191	  cp_commit();
   192	
   193	  // --- KV tile 0 prefetch --------------------------------------------------
   194	  stage_tile(k_dst, k_src, kv_pitch, step_rows);
   195	  stage_tile(v_dst, v_src, kv_pitch, step_rows);
   196	  cp_commit();
   197	
   198	  // Fragment addressing. A (Q) and K use the non-transposed map, V the
   199	  // transposed one. In each case the lane group picks which half of the 16
   200	  // wide block the lane supplies, and the lane picks the row inside it.
   201	  const int row_in_half = lane & 7;
   202	  const int k_half = ((lane >> 3) & 1) * 8;  // selects the K half of the block
   203	  const int n_half = (lane >> 4) * 8;        // selects the N half of the block
   204	  const uint32_t q_frag_addr =
   205	      smem_u32(q_smem + (warp * 16 + k_half + row_in_half) * kRowStride + n_half);
   206	  const uint32_t k_frag_addr =
   207	      smem_u32(k_smem + (n_half + row_in_half) * kRowStride + k_half);
   208	  const uint32_t v_frag_addr =
   209	      smem_u32(v_smem + (k_half + row_in_half) * kRowStride + n_half);
   210	
   211	  cp_wait_all();
   212	  __syncthreads();
   213	
   214	  // The Q tile is resident, so its fragments are read once and kept in registers.
   215	  uint32_t q_frag[8][4];
   216	#pragma unroll
   217	  for (int kt = 0; kt < 8; ++kt) ldmatrix_x4(q_frag[kt], q_frag_addr + kt * 32);
   218	
   219	  const float scaled = kLog2e * rsqrtf(static_cast<float>(kDim));
   220	  const int q_row0 = warp * 16 + (lane >> 2);
   221	  const int q_row1 = q_row0 + 8;
   222	  const int col_pair = 2 * (lane & 3);
   223	
   224	  float row_max[2] = {-CUDART_INF_F, -CUDART_INF_F};
   225	  float row_sum[2] = {0.f, 0.f};
   226	  float out[16][4];
   227	#pragma unroll
   228	  for (int i = 0; i < 16; ++i)
   229	#pragma unroll
   230	    for (int j = 0; j < 4; ++j) out[i][j] = 0.f;
   231	
   232	  for (int t = 0; t < n_tiles; ++t) {
   233	    const int stage = t & 1;
   234	    cp_wait_all();
   235	    __syncthreads();
   236	
   237	    // Buffer released: prefetch the next tile while this one is consumed.
   238	    if (t + 1 < n_tiles) {
   239	      const bf16* k_next = k_src + static_cast<int64_t>(t + 1) * kCols * kv_pitch;
   240	      const bf16* v_next = v_src + static_cast<int64_t>(t + 1) * kCols * kv_pitch;
   241	      stage_tile(k_smem + (stage ^ 1) * kKvElems + row_local * kRowStride + col,
   242	                 k_next, kv_pitch, step_rows);
   243	      stage_tile(v_smem + (stage ^ 1) * kKvElems + row_local * kRowStride + col,
   244	                 v_next, kv_pitch, step_rows);
   245	      cp_commit();
   246	    }
   247	
   248	    // --- scores: S = Q K^T -------------------------------------------------
   249	    float score[8][4];
   250	#pragma unroll
   251	    for (int i = 0; i < 8; ++i)
   252	#pragma unroll
   253	      for (int j = 0; j < 4; ++j) score[i][j] = 0.f;
   254	
   255	    const uint32_t k_stage_addr = k_frag_addr + stage * kKvElems * 2;
   256	#pragma unroll
   257	    for (int kt = 0; kt < 8; ++kt) {
   258	      uint32_t b[8][2];
   259	#pragma unroll
   260	      for (int np = 0; np < 4; ++np) {
   261	        uint32_t r[4];
   262	        ldmatrix_x4(r, k_stage_addr + (np * 16 * kRowStride + kt * 16) * 2);
   263	        b[np * 2][0] = r[0];
   264	        b[np * 2][1] = r[1];
   265	        b[np * 2 + 1][0] = r[2];
   266	        b[np * 2 + 1][1] = r[3];
   267	      }
   268	#pragma unroll
   269	      for (int nt = 0; nt < 8; ++nt) mma_16816(score[nt], q_frag[kt], b[nt]);
   270	    }
   271	
   272	    // Causal mask; only the diagonal tile holds visible/invisible key pairs.
   273	    if (t == q_tile) {
   274	      const int key0 = t * kCols + col_pair;
   275	#pragma unroll
   276	      for (int nt = 0; nt < 8; ++nt) {
   277	        const int key = key0 + nt * 8;
   278	        if (key > q0 + q_row0) score[nt][0] = -CUDART_INF_F;
   279	        if (key + 1 > q0 + q_row0) score[nt][1] = -CUDART_INF_F;
   280	        if (key > q0 + q_row1) score[nt][2] = -CUDART_INF_F;
   281	        if (key + 1 > q0 + q_row1) score[nt][3] = -CUDART_INF_F;
   282	      }
   283	    }
   284	
   285	    // --- online softmax ----------------------------------------------------
   286	    float tile_max[2] = {score[0][0], score[0][2]};
   287	#pragma unroll
   288	    for (int nt = 1; nt < 8; ++nt) {
   289	      tile_max[0] = fmaxf(tile_max[0], fmaxf(score[nt][0], score[nt][1]));
   290	      tile_max[1] = fmaxf(tile_max[1], fmaxf(score[nt][2], score[nt][3]));
   291	    }
   292	    const float new_max0 = fmaxf(row_max[0], quad_max(tile_max[0]));
   293	    const float new_max1 = fmaxf(row_max[1], quad_max(tile_max[1]));
   294	    const float alpha0 = exp2f((row_max[0] - new_max0) * scaled);
   295	    const float alpha1 = exp2f((row_max[1] - new_max1) * scaled);
   296	    row_max[0] = new_max0;
   297	    row_max[1] = new_max1;
   298	
   299	#pragma unroll
   300	    for (int nt = 0; nt < 16; ++nt) {
   301	      out[nt][0] *= alpha0;
   302	      out[nt][1] *= alpha0;
   303	      out[nt][2] *= alpha1;
   304	      out[nt][3] *= alpha1;
   305	    }
   306	
   307	    const float ref0 = new_max0 * scaled;
   308	    const float ref1 = new_max1 * scaled;
   309	    float partial0 = 0.f;
   310	    float partial1 = 0.f;
   311	    uint32_t prob[4][4];
   312	#pragma unroll
   313	    for (int kt = 0; kt < 4; ++kt) {
   314	      const float p0 = exp2f(score[kt * 2][0] * scaled - ref0);
   315	      const float p1 = exp2f(score[kt * 2][1] * scaled - ref0);
   316	      const float p2 = exp2f(score[kt * 2][2] * scaled - ref1);
   317	      const float p3 = exp2f(score[kt * 2][3] * scaled - ref1);
   318	      const float p4 = exp2f(score[kt * 2 + 1][0] * scaled - ref0);
   319	      const float p5 = exp2f(score[kt * 2 + 1][1] * scaled - ref0);
   320	      const float p6 = exp2f(score[kt * 2 + 1][2] * scaled - ref1);
   321	      const float p7 = exp2f(score[kt * 2 + 1][3] * scaled - ref1);
   322	      partial0 += (p0 + p1) + (p4 + p5);
   323	      partial1 += (p2 + p3) + (p6 + p7);
   324	      prob[kt][0] = pack_bf16(p0, p1);
   325	      prob[kt][1] = pack_bf16(p2, p3);
   326	      prob[kt][2] = pack_bf16(p4, p5);
   327	      prob[kt][3] = pack_bf16(p6, p7);
   328	    }
   329	    row_sum[0] = row_sum[0] * alpha0 + quad_sum(partial0);
   330	    row_sum[1] = row_sum[1] * alpha1 + quad_sum(partial1);
   331	
   332	    // --- O += P V ----------------------------------------------------------
   333	    const uint32_t v_stage_addr = v_frag_addr + stage * kKvElems * 2;
   334	#pragma unroll
   335	    for (int kt = 0; kt < 4; ++kt) {
   336	      uint32_t b[16][2];
   337	#pragma unroll
   338	      for (int np = 0; np < 8; ++np) {
   339	        uint32_t r[4];
   340	        ldmatrix_x4_trans(r, v_stage_addr + (kt * 16 * kRowStride + np * 16) * 2);
   341	        b[np * 2][0] = r[0];
   342	        b[np * 2][1] = r[1];
   343	        b[np * 2 + 1][0] = r[2];
   344	        b[np * 2 + 1][1] = r[3];
   345	      }
   346	#pragma unroll
   347	      for (int nt = 0; nt < 16; ++nt) mma_16816(out[nt], prob[kt], b[nt]);
   348	    }
   349	  }
   350	
   351	  // --- normalize and store ------------------------------------------------
   352	  const float inv0 = __frcp_rn(row_sum[0]);
   353	  const float inv1 = __frcp_rn(row_sum[1]);
   354	  bf16* o0 = og + batch_q + static_cast<int64_t>(q0 + q_row0) * q_pitch +
   355	             static_cast<int64_t>(head) * kDim + col_pair;
   356	  bf16* o1 = og + batch_q + static_cast<int64_t>(q0 + q_row1) * q_pitch +
   357	             static_cast<int64_t>(head) * kDim + col_pair;
   358	#pragma unroll
   359	  for (int nt = 0; nt < 16; ++nt) {
   360	    *reinterpret_cast<__nv_bfloat162*>(o0 + nt * 8) =
   361	        __floats2bfloat162_rn(out[nt][0] * inv0, out[nt][1] * inv0);
   362	    *reinterpret_cast<__nv_bfloat162*>(o1 + nt * 8) =
   363	        __floats2bfloat162_rn(out[nt][2] * inv1, out[nt][3] * inv1);
   364	  }
   365	}
   366	
   367	// ---------------------------------------------------------------------------
   368	// Host wrapper
   369	// ---------------------------------------------------------------------------
   370	
   371	void check_input(const torch::Tensor& tensor, const char* name, int64_t batch,
   372	                 int64_t heads) {
   373	  TORCH_CHECK_VALUE(tensor.is_cuda(), name, " must be a CUDA tensor");
   374	  TORCH_CHECK_TYPE(tensor.scalar_type() == torch::kBFloat16, name,
   375	                   " must be bfloat16");
   376	  TORCH_CHECK_VALUE(tensor.dim() == 4, name, " must be rank 4");
   377	  TORCH_CHECK_VALUE(tensor.size(0) == batch, name, " batch mismatch");
   378	  TORCH_CHECK_VALUE(tensor.size(2) == heads, name, " head count mismatch");
   379	  TORCH_CHECK_VALUE(tensor.size(3) == kDim, name, " head dim must be 128");
   380	  TORCH_CHECK_VALUE(tensor.is_contiguous(), name, " must be contiguous BSHD");
   381	}
   382	
   383	void kernel(const torch::Tensor& q, const torch::Tensor& k,
   384	            const torch::Tensor& v, torch::Tensor& o) {
   385	  const int64_t batch = q.size(0);
   386	  const int64_t seq = q.size(1);
   387	  const int64_t q_heads = q.size(2);
   388	  const int64_t kv_heads = k.size(2);
   389	  check_input(q, "q", batch, q_heads);
   390	  check_input(k, "k", batch, kv_heads);
   391	  check_input(v, "v", batch, kv_heads);
   392	  TORCH_CHECK_VALUE(o.is_cuda() && o.scalar_type() == torch::kBFloat16,
   393	                    "o must be a CUDA bfloat16 tensor");
   394	  TORCH_CHECK_VALUE(o.is_contiguous() && o.sizes() == q.sizes(),
   395	                    "o must be a contiguous q-shaped tensor");
   396	  TORCH_CHECK_VALUE(k.sizes() == v.sizes(), "k and v must share a shape");
   397	  TORCH_CHECK_VALUE(seq % kRows == 0, "sequence must be a multiple of 64");
   398	  TORCH_CHECK_VALUE(q_heads % kv_heads == 0 && q_heads > 0,
   399	                    "query heads must be a multiple of KV heads");
   400	  if (seq == 0) return;
   401	
   402	  const c10::cuda::CUDAGuard guard(q.device());
   403	  const cudaStream_t stream =
   404	      c10::cuda::getCurrentCUDAStream(q.get_device()).stream();
   405	
   406	  static bool configured = false;
   407	  if (!configured) {
   408	    const cudaError_t status = cudaFuncSetAttribute(
   409	        gqa_kernel, cudaFuncAttributeMaxDynamicSharedMemorySize, kSmemBytes);
   410	    TORCH_CHECK(status == cudaSuccess, cudaGetErrorString(status));
   411	    configured = true;
   412	  }
   413	
   414	  const int q_tiles = static_cast<int>(seq / kRows);
   415	  const dim3 grid(q_tiles, static_cast<unsigned>(q_heads),
   416	                  static_cast<unsigned>(batch));
   417	  gqa_kernel<<<grid, kThreads, kSmemBytes, stream>>>(
   418	      reinterpret_cast<const bf16*>(q.data_ptr()),
   419	      reinterpret_cast<const bf16*>(k.data_ptr()),
   420	      reinterpret_cast<const bf16*>(v.data_ptr()),
   421	      reinterpret_cast<bf16*>(o.data_ptr()), static_cast<int>(seq),
   422	      static_cast<int>(q_heads * kDim), static_cast<int>(kv_heads * kDim),
   423	      static_cast<int>(q_heads / kv_heads), q_tiles);
   424	  const cudaError_t error = cudaGetLastError();
   425	  TORCH_CHECK(error == cudaSuccess, cudaGetErrorString(error));
   426	}
