        if (key + 1 > q0 + q_row0) score[nt][1] = -CUDART_INF_F;
        if (key > q0 + q_row1) score[nt][2] = -CUDART_INF_F;
        if (key + 1 > q0 + q_row1) score[nt][3] = -CUDART_INF_F;
